<?php require_once __DIR__."/../config/database.php";require_once __DIR__."/../includes/functions.php";header("Content-Type: application/json");if(!isLoggedIn()){echo json_encode([]);exit;}$q=trim($_GET["q"]??"");if(strlen($q)<2){echo json_encode([]);exit;}$r=[];$l="%$q%";foreach(dbQuery("SELECT id,nim,nama FROM mahasiswa WHERE nama LIKE ? OR nim LIKE ? LIMIT 5",[$l,$l]) as $m)$r[]=["type"=>"Mahasiswa","label"=>$m["nama"]." (".$m["nim"].")","url"=>BASE_URL."/pages/mahasiswa.php"];foreach(dbQuery("SELECT id,nomor_surat,nama_penerima FROM surat WHERE nomor_surat LIKE ? OR nama_penerima LIKE ? LIMIT 5",[$l,$l]) as $s)$r[]=["type"=>"Surat","label"=>$s["nomor_surat"]." - ".$s["nama_penerima"],"url"=>BASE_URL."/pages/surat.php"];echo json_encode($r);
